package com.printflow.files;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import org.springframework.stereotype.Component;
@Component public class ReferenceReviewPdf {
 private final Semaphore slots=new Semaphore(2);
 public byte[] create(Path source,String mime,String json)throws java.io.IOException{if(!slots.tryAcquire())throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.TOO_MANY_REQUESTS,"Review export busy; retry shortly");Process child=null;Path job=null,out=null;try{
  job=Files.createTempFile(source.getParent(),"review-",".json");out=Files.createTempFile(source.getParent(),"review-",".pdf");Files.writeString(job,json);
  String executable=Path.of(System.getProperty("java.home"),"bin",System.getProperty("os.name").startsWith("Windows")?"java.exe":"java").toString();var command=new ArrayList<String>(List.of(executable,"-Xmx192m","-Djava.awt.headless=true"));boolean boot;try{Class.forName("org.springframework.boot.loader.launch.PropertiesLauncher");boot=true;}catch(ClassNotFoundException absent){boot=false;}if(boot)command.add("-Dloader.main=com.printflow.files.ReferenceReviewWorker");String cp=System.getProperty("java.class.path");if(!boot){var paths=new LinkedHashSet<String>();paths.add(cp);for(ClassLoader loader=getClass().getClassLoader();loader!=null;loader=loader.getParent())if(loader instanceof java.net.URLClassLoader urls)for(var url:urls.getURLs())if(url.getProtocol().equals("file"))paths.add(Path.of(url.toURI()).toString());cp=String.join(java.io.File.pathSeparator,paths);}command.addAll(List.of("-cp",cp,boot?"org.springframework.boot.loader.launch.PropertiesLauncher":"com.printflow.files.ReferenceReviewWorker",source.toString(),mime,job.toString(),out.toString()));child=new ProcessBuilder(command).redirectError(ProcessBuilder.Redirect.DISCARD).redirectOutput(ProcessBuilder.Redirect.DISCARD).start();if(!child.waitFor(20,TimeUnit.SECONDS)){child.destroyForcibly();throw new java.io.IOException("Export timed out");}if(child.exitValue()!=0||Files.size(out)==0||Files.size(out)>15*1024*1024)throw new java.io.IOException("Export unsupported");return Files.readAllBytes(out);
 }catch(Exception e){if(e instanceof InterruptedException)Thread.currentThread().interrupt();throw new java.io.IOException("Review copy could not be created. Ask the team for a simpler PDF or image.");}finally{if(child!=null&&child.isAlive())try{child.destroyForcibly().waitFor(2,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}try{if(job!=null)Files.deleteIfExists(job);}finally{try{if(out!=null)Files.deleteIfExists(out);}finally{slots.release();}}}}
}
